create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public;

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text,
  phone text,
  avatar_url text,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table public.user_roles (
  user_id uuid not null references public.profiles(id) on delete cascade,
  role text not null check (role in ('customer','seller','admin')),
  created_at timestamptz not null default timezone('utc', now()),
  primary key (user_id, role)
);

create table public.shops (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles(id) on delete restrict,
  name text not null,
  slug text not null unique,
  description text,
  logo_url text,
  status text not null default 'pending' check (status in ('pending','active','suspended')),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table public.product_categories (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  image_url text,
  is_visible boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table public.products (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id) on delete restrict,
  category_id uuid references public.product_categories(id) on delete set null,
  name text not null,
  slug text not null unique,
  description text,
  price numeric(12,2) not null check (price >= 0),
  compare_at_price numeric(12,2) check (compare_at_price is null or compare_at_price >= price),
  currency char(3) not null default 'THB',
  sku text,
  stock_quantity integer not null default 0 check (stock_quantity >= 0),
  status text not null default 'draft' check (status in ('draft','published','archived')),
  origin text,
  rating numeric(2,1) not null default 0 check (rating >= 0 and rating <= 5),
  review_count integer not null default 0 check (review_count >= 0),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table public.product_variants (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products(id) on delete cascade,
  name text not null,
  sku text,
  price numeric(12,2) check (price is null or price >= 0),
  stock_quantity integer not null default 0 check (stock_quantity >= 0),
  is_active boolean not null default true,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table public.product_images (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products(id) on delete cascade,
  storage_path text not null,
  alt_text text,
  sort_order integer not null default 0,
  created_at timestamptz not null default timezone('utc', now())
);

create table public.stories (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  slug text not null unique,
  summary text,
  body text,
  cover_image_path text,
  category text,
  status text not null default 'draft' check (status in ('draft','published','archived')),
  published_at timestamptz,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table public.addresses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  recipient_name text not null,
  phone text not null,
  line1 text not null,
  line2 text,
  subdistrict text,
  district text,
  province text not null,
  postal_code text not null,
  country_code char(2) not null default 'TH',
  is_default boolean not null default false,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table public.carts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null unique references public.profiles(id) on delete cascade,
  currency char(3) not null default 'THB',
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table public.cart_items (
  id uuid primary key default gen_random_uuid(),
  cart_id uuid not null references public.carts(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete restrict,
  variant_id uuid references public.product_variants(id) on delete set null,
  quantity integer not null check (quantity > 0),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  unique nulls not distinct (cart_id, product_id, variant_id)
);

create table public.orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null unique default ('HB-' || upper(encode(gen_random_bytes(6), 'hex'))),
  buyer_id uuid not null references public.profiles(id) on delete restrict,
  shipping_address jsonb not null,
  currency char(3) not null default 'THB',
  subtotal numeric(12,2) not null check (subtotal >= 0),
  shipping_fee numeric(12,2) not null default 0 check (shipping_fee >= 0),
  discount_amount numeric(12,2) not null default 0 check (discount_amount >= 0),
  total numeric(12,2) not null check (total >= 0),
  status text not null default 'pending' check (status in ('pending','confirmed','processing','shipped','delivered','cancelled','refunded')),
  payment_status text not null default 'pending' check (payment_status in ('pending','authorized','paid','failed','refunded')),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders(id) on delete cascade,
  shop_id uuid not null references public.shops(id) on delete restrict,
  product_id uuid references public.products(id) on delete set null,
  variant_id uuid references public.product_variants(id) on delete set null,
  product_name text not null,
  sku text,
  unit_price numeric(12,2) not null check (unit_price >= 0),
  quantity integer not null check (quantity > 0),
  line_total numeric(12,2) not null check (line_total >= 0),
  created_at timestamptz not null default timezone('utc', now())
);

create table public.payments (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders(id) on delete restrict,
  provider text not null,
  provider_reference text unique,
  amount numeric(12,2) not null check (amount >= 0),
  currency char(3) not null default 'THB',
  status text not null default 'pending' check (status in ('pending','authorized','paid','failed','refunded')),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create index profiles_phone_idx on public.profiles(phone);
create index user_roles_user_id_idx on public.user_roles(user_id);
create index shops_owner_id_idx on public.shops(owner_id);
create index products_shop_status_idx on public.products(shop_id, status);
create index products_category_status_idx on public.products(category_id, status);
create index product_variants_product_id_idx on public.product_variants(product_id);
create index product_images_product_id_idx on public.product_images(product_id, sort_order);
create index stories_status_published_at_idx on public.stories(status, published_at desc);
create index addresses_user_id_idx on public.addresses(user_id);
create unique index addresses_one_default_per_user_idx on public.addresses(user_id) where is_default;
create index cart_items_cart_id_idx on public.cart_items(cart_id);
create index orders_buyer_created_at_idx on public.orders(buyer_id, created_at desc);
create index order_items_order_id_idx on public.order_items(order_id);
create index order_items_shop_id_idx on public.order_items(shop_id);
create index payments_order_id_idx on public.payments(order_id);

create or replace function public.set_updated_at() returns trigger language plpgsql set search_path = public as $$ begin new.updated_at = timezone('utc', now()); return new; end; $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id, display_name) values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name')) on conflict (id) do nothing; insert into public.user_roles(user_id, role) values (new.id, 'customer') on conflict do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

create or replace function private.has_role(target_role text) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.user_roles where user_id = (select auth.uid()) and role = target_role); $$;
create or replace function private.is_platform_admin() returns boolean language sql stable security definer set search_path = public as $$ select private.has_role('admin'); $$;
create or replace function private.owns_shop(target_shop_id uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.shops where id = target_shop_id and owner_id = (select auth.uid())); $$;

alter table public.profiles enable row level security;
alter table public.user_roles enable row level security;
alter table public.shops enable row level security;
alter table public.product_categories enable row level security;
alter table public.products enable row level security;
alter table public.product_variants enable row level security;
alter table public.product_images enable row level security;
alter table public.stories enable row level security;
alter table public.addresses enable row level security;
alter table public.carts enable row level security;
alter table public.cart_items enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.payments enable row level security;

create policy profiles_select_own on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy profiles_update_own on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
create policy roles_select_own on public.user_roles for select to authenticated using ((select auth.uid()) = user_id);
create policy shops_public_read on public.shops for select to anon, authenticated using (status = 'active');
create policy shops_seller_manage on public.shops for all to authenticated using ((select private.owns_shop(id)) or (select private.is_platform_admin())) with check ((select private.is_platform_admin()) or ((select private.has_role('seller')) and owner_id = (select auth.uid())));
create policy categories_public_read on public.product_categories for select to anon, authenticated using (is_visible);
create policy categories_admin_manage on public.product_categories for all to authenticated using ((select private.is_platform_admin())) with check ((select private.is_platform_admin()));
create policy products_public_read on public.products for select to anon, authenticated using (status = 'published');
create policy products_seller_manage on public.products for all to authenticated using ((select private.owns_shop(shop_id)) or (select private.is_platform_admin())) with check ((select private.owns_shop(shop_id)) or (select private.is_platform_admin()));
create policy variants_public_read on public.product_variants for select to anon, authenticated using (is_active);
create policy variants_seller_manage on public.product_variants for all to authenticated using (exists (select 1 from public.products where products.id = product_variants.product_id and ((select private.owns_shop(products.shop_id)) or (select private.is_platform_admin())))) with check (exists (select 1 from public.products where products.id = product_variants.product_id and ((select private.owns_shop(products.shop_id)) or (select private.is_platform_admin()))));
create policy images_public_read on public.product_images for select to anon, authenticated using (true);
create policy images_seller_manage on public.product_images for all to authenticated using (exists (select 1 from public.products where products.id = product_images.product_id and ((select private.owns_shop(products.shop_id)) or (select private.is_platform_admin())))) with check (exists (select 1 from public.products where products.id = product_images.product_id and ((select private.owns_shop(products.shop_id)) or (select private.is_platform_admin()))));
create policy stories_public_read on public.stories for select to anon, authenticated using (status = 'published');
create policy stories_admin_manage on public.stories for all to authenticated using ((select private.is_platform_admin())) with check ((select private.is_platform_admin()));
create policy addresses_own_manage on public.addresses for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy carts_own_manage on public.carts for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy cart_items_own_manage on public.cart_items for all to authenticated using (exists (select 1 from public.carts where carts.id = cart_items.cart_id and carts.user_id = (select auth.uid()))) with check (exists (select 1 from public.carts where carts.id = cart_items.cart_id and carts.user_id = (select auth.uid())));
create policy orders_buyer_read on public.orders for select to authenticated using ((select auth.uid()) = buyer_id);
create policy order_items_buyer_read on public.order_items for select to authenticated using (exists (select 1 from public.orders where orders.id = order_items.order_id and orders.buyer_id = (select auth.uid())));
create policy payments_buyer_read on public.payments for select to authenticated using (exists (select 1 from public.orders where orders.id = payments.order_id and orders.buyer_id = (select auth.uid())));

grant usage on schema public to anon, authenticated;
grant usage on schema private to authenticated;
grant execute on all functions in schema private to authenticated;
grant select on public.shops, public.product_categories, public.products, public.product_variants, public.product_images, public.stories to anon, authenticated;
grant select, insert, update, delete on public.profiles, public.addresses, public.carts, public.cart_items to authenticated;
grant select on public.user_roles, public.orders, public.order_items, public.payments to authenticated;
grant all on all tables in schema public to service_role;

create trigger profiles_set_updated_at before update on public.profiles for each row execute procedure public.set_updated_at();
create trigger shops_set_updated_at before update on public.shops for each row execute procedure public.set_updated_at();
create trigger categories_set_updated_at before update on public.product_categories for each row execute procedure public.set_updated_at();
create trigger products_set_updated_at before update on public.products for each row execute procedure public.set_updated_at();
create trigger variants_set_updated_at before update on public.product_variants for each row execute procedure public.set_updated_at();
create trigger stories_set_updated_at before update on public.stories for each row execute procedure public.set_updated_at();
create trigger addresses_set_updated_at before update on public.addresses for each row execute procedure public.set_updated_at();
create trigger carts_set_updated_at before update on public.carts for each row execute procedure public.set_updated_at();
create trigger cart_items_set_updated_at before update on public.cart_items for each row execute procedure public.set_updated_at();
create trigger orders_set_updated_at before update on public.orders for each row execute procedure public.set_updated_at();
create trigger payments_set_updated_at before update on public.payments for each row execute procedure public.set_updated_at();
